const getGrades=()=>load('grades',[]);
const getAudit=()=>load('audit',[]);
const getSettings=()=>load('settings',{schoolName:'วิทยาลัยเทคนิคนางรอง',department:'แผนกคอมพิวเตอร์',semester:'1/2569',latePolicy:'allow-by-worksheet'});
function setData(k,v){save(k,v)}
function audit(action,detail,actor){let a=getAudit();a.unshift({id:uid(),at:new Date().toISOString(),action,detail,actor:actor||currentUser()?.name||'System'});setData('audit',a.slice(0,500));}
function currentUser(){let users=getUsers();if(state.role==='admin')return users.find(x=>x.role==='admin')||users[0];return users.find(x=>x.id===state.userId)||users.find(x=>x.role==='user')}
function toast(msg,type='success'){let d=document.createElement('div');d.className='toast '+type;d.textContent=msg;toastRoot.appendChild(d);setTimeout(()=>d.remove(),2600)}
function pill(text,tone='gray'){return `<span class="pill ${tone}">${esc(text)}</span>`}
function statusPill(status){if(status==='published')return pill('เผยแพร่แล้ว','green');if(status==='closed')return pill('ปิดรับงาน','red');return pill('Draft','amber')}
function typePill(type){return pill(type==='digital'?'Digital':'Paper',type==='digital'?'':'gray')}
function modal(title,body,foot=''){return `<div class="modal-backdrop" data-close-modal><section class="modal" onclick="event.stopPropagation()"><header class="modal-head"><div><b>${title}</b></div><button class="iconbtn" data-close-modal>✕</button></header><div class="modal-body">${body}</div>${foot?`<footer class="modal-foot">${foot}</footer>`:''}</section></div>`}
function stat(icon,label,value,trend=''){return `<div class="card stat"><div class="stat-top"><span class="muted">${label}</span><span>${icon}</span></div><div class="num">${value}</div>${trend?`<div class="trend">${trend}</div>`:''}</div>`}
function pageHead(title,desc,actions=''){return `<div class="page-head"><div><h1 class="page-title">${title}</h1><p class="page-desc">${desc}</p></div><div class="action-row">${actions}</div></div>`}
function resetDemo(){Object.keys(localStorage).filter(k=>k.startsWith(STORE)).forEach(k=>localStorage.removeItem(k));toast('รีเซ็ตข้อมูลทดสอบแล้ว');state.page='dashboard';render()}
function login(role,userId=''){state.role=role;state.userId=userId||(role==='user'?'U001':'UADMIN');sessionStorage.setItem('docfull.v5.role',role);sessionStorage.setItem('docfull.v5.uid',state.userId);state.page='dashboard';audit('LOGIN',role);render()}
function logout(){if(state.scanStream)stopCamera();sessionStorage.removeItem('docfull.v5.role');sessionStorage.removeItem('docfull.v5.uid');state.role=null;state.userId='';state.page='dashboard';renderLogin()}
function renderLogin(){
 app.innerHTML=`<div class="login"><section class="login-hero"><div><div class="brandline"><div class="brandmark">▦</div>DOC-FULL-NR Smart Worksheet</div><h1>จัดการใบงาน<br>ครบในระบบเดียว</h1><p>สร้างใบงาน Digital/Paper · มอบหมาย · ส่งงาน · สแกน QR · ตรวจงาน · รายงาน · พิมพ์ PDF · Audit Log</p><div class="login-features"><div>✓ Responsive ทุกอุปกรณ์</div><div>✓ แยก Admin / User ชัดเจน</div><div>✓ UX สถานะ Loading / Empty / Error</div><div>✓ พร้อมเชื่อม Firebase จริง</div></div></div><div class="small">V5 Full UX/UI Functional Sandbox · ข้อมูลทดสอบไม่เขียน Firestore จริง</div></section><section class="login-panel"><div class="login-box"><h2>เข้าสู่ระบบ</h2><p class="muted">ระบบจัดการใบงานสำหรับครูและนักเรียน</p><div class="demo-box"><b>โหมดทดสอบเต็ม</b><p class="small muted">เลือกบทบาทเพื่อทดสอบทุกหน้าของระบบ</p><div class="demo-actions"><button class="btn btn-primary" id="demo-admin">ทดลอง Admin</button><button class="btn btn-secondary" id="demo-user">ทดลอง User</button></div></div><form class="form-stack" id="login-form"><div><label class="label">อีเมล</label><input class="field" id="login-email" type="email" placeholder="name@example.com"></div><div><label class="label">รหัสผ่าน</label><div class="password-wrap"><input class="field" id="login-pass" type="password" placeholder="••••••••"><button type="button" class="iconbtn" id="toggle-pass">◉</button></div></div><div style="display:flex;justify-content:space-between;gap:10px;align-items:center"><label class="small"><input type="checkbox"> จดจำการเข้าสู่ระบบ</label><button type="button" class="btn btn-ghost" id="forgot">ลืมรหัสผ่าน</button></div><button class="btn btn-primary" type="submit">เข้าสู่ระบบ</button></form><p class="small muted" style="text-align:center;margin-top:18px">บัญชีจริงจะใช้ Firebase Authentication เมื่อเชื่อม Production</p></div></section></div>`;
 document.querySelector('#demo-admin').onclick=()=>login('admin','UADMIN');
 document.querySelector('#demo-user').onclick=()=>login('user','U001');
 document.querySelector('#toggle-pass').onclick=()=>{let p=document.querySelector('#login-pass');p.type=p.type==='password'?'text':'password'};
 document.querySelector('#forgot').onclick=()=>toast('โหมดทดสอบ: หน้าลืมรหัสผ่านพร้อมเชื่อม Firebase Auth','success');
 document.querySelector('#login-form').onsubmit=e=>{e.preventDefault();toast('โหมดทดสอบ: ใช้ปุ่ม ทดลอง Admin / ทดลอง User','error')};
}
const ADMIN_NAV=[
 ['dashboard','⌂','ภาพรวม'],['users','♙','ผู้ใช้งาน'],['classrooms','▦','ห้องเรียน'],['subjects','▤','รายวิชา'],
 ['worksheets','▧','ใบงาน'],['grading','✓','ตรวจงาน'],['reports','▥','รายงาน'],['audit','≡','Audit Log'],['settings','⚙','ตั้งค่าระบบ'],['profile','●','โปรไฟล์']
];
const USER_NAV=[['dashboard','⌂','หน้าหลัก'],['worksheets','▧','ใบงาน'],['scan','⌗','สแกน'],['profile','●','โปรไฟล์']];
function shell(content){
 const nav=state.role==='admin'?ADMIN_NAV:USER_NAV,u=currentUser(),settings=getSettings();
 return `<div class="drawer-overlay" id="overlay"></div><div class="app-shell"><aside class="sidebar" id="sidebar"><div class="brand"><div class="logo">NR</div><div><div>DOC-FULL-NR</div><div class="role">${state.role==='admin'?'Administrator':'Student Portal'}</div></div></div><div class="nav-group">${state.role==='admin'?'Management':'Workspace'}</div>${nav.map(x=>`<button class="navbtn ${state.page===x[0]||state.page.startsWith(x[0]+':')?'active':''}" data-nav="${x[0]}"><span class="ico">${x[1]}</span>${x[2]}</button>`).join('')}<div class="sidebar-footer"><div class="user-mini"><div class="avatar">${esc((u?.name||'U').slice(0,1))}</div><div><b style="color:white">${esc(u?.name||'-')}</b><div class="small">${state.role}</div></div></div><button class="navbtn" id="logout"><span class="ico">↪</span>ออกจากระบบ</button></div></aside><section class="workspace"><header class="topbar"><div class="topbar-left"><button class="iconbtn mobile-menu" id="mobile-menu">☰</button><div><b>${esc(settings.schoolName)}</b><div class="small muted">${esc(settings.department)} · ภาคเรียน ${esc(settings.semester)}</div></div></div><div class="topbar-right"><button class="iconbtn hide-mobile" id="notify">🔔</button><button class="iconbtn" id="quick">＋</button><div class="avatar">${esc((u?.name||'U').slice(0,1))}</div></div></header><main class="page">${content}</main></section></div>${state.modal||''}`;
}
function bindShell(){
 document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{if(state.scanStream)stopCamera();state.page=b.dataset.nav;state.modal=null;render()});
 document.querySelector('#logout').onclick=logout;
 let mm=document.querySelector('#mobile-menu'),sb=document.querySelector('#sidebar'),ov=document.querySelector('#overlay');
 if(mm)mm.onclick=()=>{sb.classList.add('open');ov.classList.add('show')};if(ov)ov.onclick=()=>{sb.classList.remove('open');ov.classList.remove('show')};
 document.querySelector('#notify').onclick=()=>toast('ไม่มีการแจ้งเตือนใหม่');
 document.querySelector('#quick').onclick=()=>{state.page=state.role==='admin'?'worksheets':'scan';render()};
 document.querySelectorAll('[data-close-modal]').forEach(x=>x.onclick=()=>{state.modal=null;render()});
}
function adminDashboard(){
 let users=getUsers(),cls=getClassrooms(),subs=getSubjects(),w=getWorksheets(),s=getSubmissions(),g=getGrades();
 let recent=getAudit().slice(0,6);
 return pageHead('ภาพรวม','สถานะระบบและงานที่ต้องจัดการ',`<button class="btn btn-secondary" id="reset-demo">↻ รีเซ็ตข้อมูลทดสอบ</button><button class="btn btn-primary" data-go="worksheets">＋ สร้างใบงาน</button>`)+
 `<div class="stats">${stat('♙','ผู้ใช้งาน',users.length,'พร้อมใช้งาน')}${stat('▦','ห้องเรียน',cls.length)}${stat('▧','ใบงาน',w.length,w.filter(x=>x.status==='published').length+' เผยแพร่')}${stat('✓','ส่งงานแล้ว',s.length,g.length+' ตรวจแล้ว')}</div>
 <div class="grid-2"><section class="card"><div class="page-head"><div><b>ใบงานใกล้ครบกำหนด</b><p class="small muted">ติดตามงานที่กำลังเปิดรับ</p></div></div><div style="margin-top:10px">${w.filter(x=>x.status==='published').slice(0,5).map(x=>`<div style="display:flex;justify-content:space-between;gap:10px;padding:12px 0;border-bottom:1px solid #eef2f7"><div><b>${esc(x.title)}</b><div class="small muted">${esc(x.subjectCode)} · ${x.type}</div></div><div class="small"><span class="countdown" data-due="${x.dueAt}"></span></div></div>`).join('')}</div></section>
 <section class="card"><b>กิจกรรมล่าสุด</b><div style="margin-top:10px">${recent.length?recent.map(a=>`<div style="padding:10px 0;border-bottom:1px solid #eef2f7"><b class="small">${esc(a.action)}</b><div class="small muted">${esc(a.detail)} · ${fmtDate(a.at)}</div></div>`).join(''):'<div class="empty">ยังไม่มีกิจกรรม</div>'}</div></section></div>`;
}
function countdowns(){document.querySelectorAll('[data-due]').forEach(el=>{let due=new Date(el.dataset.due).getTime(),d=due-Date.now();if(d<=0)el.textContent='ครบกำหนดแล้ว';else{let day=Math.floor(d/86400000),hr=Math.floor((d%86400000)/3600000);el.textContent=`เหลือ ${day} วัน ${hr} ชม.`}})}
function usersPage(){
 let users=getUsers(),cls=getClassrooms(),q=state.filters.userQ||'',roleF=state.filters.userRole||'all';
 let rows=users.filter(u=>(roleF==='all'||u.role===roleF)&&(!q||(`${u.name} ${u.email}`).toLowerCase().includes(q.toLowerCase())));
 return pageHead('ผู้ใช้งาน','จัดการบัญชี บทบาท สถานะ และห้องเรียน',`<button class="btn btn-primary" id="new-user">＋ เพิ่มผู้ใช้</button>`)+
 `<div class="toolbar" style="margin-top:18px"><div class="searchbox grow"><span class="mag">⌕</span><input class="field" id="user-search" placeholder="ค้นหาชื่อหรืออีเมล" value="${esc(q)}"></div><select class="field" id="user-role-filter"><option value="all">ทุกบทบาท</option><option value="admin" ${roleF==='admin'?'selected':''}>Admin</option><option value="user" ${roleF==='user'?'selected':''}>User</option></select></div>
 <div class="table-wrap"><table class="table"><thead><tr><th>ผู้ใช้งาน</th><th>บทบาท</th><th>ห้องเรียน</th><th>สถานะ</th><th>จัดการ</th></tr></thead><tbody>${rows.map(u=>`<tr><td><b>${esc(u.name)}</b><div class="small muted">${esc(u.email)}</div></td><td>${pill(u.role,u.role==='admin'?'red':'gray')}</td><td>${esc(cls.find(c=>c.id===u.classroomId)?.name||'-')}</td><td>${u.active?pill('ใช้งาน','green'):pill('ระงับ','red')}</td><td><div class="action-row"><button class="btn btn-secondary" data-edit-user="${u.id}">แก้ไข</button><button class="btn ${u.active?'btn-danger':'btn-success'}" data-toggle-user="${u.id}">${u.active?'ระงับ':'เปิดใช้'}</button></div></td></tr>`).join('')}</tbody></table></div>`;
}
function userForm(u={}){
 let cls=getClassrooms();
 return `<div class="form-grid"><div><label class="label">ชื่อ-สกุล</label><input class="field" id="uf-name" value="${esc(u.name||'')}"></div><div><label class="label">อีเมล</label><input class="field" id="uf-email" type="email" value="${esc(u.email||'')}"></div><div><label class="label">บทบาท</label><select class="field" id="uf-role"><option value="user" ${u.role==='user'?'selected':''}>User</option><option value="admin" ${u.role==='admin'?'selected':''}>Admin</option></select></div><div><label class="label">ห้องเรียน</label><select class="field" id="uf-class"><option value="">ไม่ระบุ</option>${cls.map(c=>`<option value="${c.id}" ${u.classroomId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div></div>`;
}
function bindUsers(){
 let s=document.querySelector('#user-search');if(s)s.oninput=e=>{state.filters.userQ=e.target.value;render()};
 let f=document.querySelector('#user-role-filter');if(f)f.onchange=e=>{state.filters.userRole=e.target.value;render()};
 let nu=document.querySelector('#new-user');if(nu)nu.onclick=()=>{state.editing=null;state.modal=modal('เพิ่มผู้ใช้งาน',userForm(),`<button class="btn btn-secondary" data-close-modal>ยกเลิก</button><button class="btn btn-primary" id="save-user">บันทึก</button>`);render()};
 document.querySelectorAll('[data-edit-user]').forEach(b=>b.onclick=()=>{let u=getUsers().find(x=>x.id===b.dataset.editUser);state.editing=u.id;state.modal=modal('แก้ไขผู้ใช้งาน',userForm(u),`<button class="btn btn-secondary" data-close-modal>ยกเลิก</button><button class="btn btn-primary" id="save-user">บันทึก</button>`);render()});
 document.querySelectorAll('[data-toggle-user]').forEach(b=>b.onclick=()=>{let users=getUsers(),u=users.find(x=>x.id===b.dataset.toggleUser);u.active=!u.active;setData('users',users);audit('TOGGLE_USER',u.email+' -> '+u.active);toast('อัปเดตสถานะแล้ว');render()});
 let sv=document.querySelector('#save-user');if(sv)sv.onclick=()=>{let name=document.querySelector('#uf-name').value.trim(),email=document.querySelector('#uf-email').value.trim();if(!name||!/^\S+@\S+\.\S+$/.test(email))return toast('กรอกชื่อและอีเมลให้ถูกต้อง','error');let users=getUsers();if(state.editing)Object.assign(users.find(x=>x.id===state.editing),{name,email,role:document.querySelector('#uf-role').value,classroomId:document.querySelector('#uf-class').value});else users.push({id:'U'+Date.now(),name,email,role:document.querySelector('#uf-role').value,classroomId:document.querySelector('#uf-class').value,active:true});setData('users',users);audit(state.editing?'UPDATE_USER':'CREATE_USER',email);state.modal=null;toast('บันทึกผู้ใช้งานแล้ว');render()};
}
function classroomsPage(){
 let cls=getClassrooms();
 return pageHead('ห้องเรียน','จัดการชั้นเรียน จำนวนนักเรียน และสถานะ',`<button class="btn btn-primary" id="new-class">＋ เพิ่มห้องเรียน</button>`)+
 `<div class="cards">${cls.map(c=>`<article class="card"><div class="page-head"><div><h3 style="margin:0">${esc(c.name)}</h3><p class="small muted">${esc(c.level)} · ห้อง ${esc(c.room)}</p></div>${c.active?pill('ใช้งาน','green'):pill('ปิด','red')}</div><div style="font-size:28px;font-weight:900;margin-top:14px">${c.studentCount}</div><div class="small muted">นักเรียน</div><div class="worksheet-actions"><button class="btn btn-secondary" data-edit-class="${c.id}">แก้ไข</button><button class="btn btn-secondary" data-open-users="${c.id}">ดูสมาชิก</button></div></article>`).join('')}</div>`;
}
function classForm(c={}){return `<div class="form-grid"><div><label class="label">ชื่อห้อง</label><input class="field" id="cf-name" value="${esc(c.name||'')}"></div><div><label class="label">ระดับ</label><input class="field" id="cf-level" value="${esc(c.level||'')}"></div><div><label class="label">ห้อง</label><input class="field" id="cf-room" value="${esc(c.room||'')}"></div><div><label class="label">จำนวนนักเรียน</label><input class="field" id="cf-count" type="number" min="0" value="${c.studentCount??0}"></div></div>`}
function bindClassrooms(){
 let nc=document.querySelector('#new-class');if(nc)nc.onclick=()=>{state.editing=null;state.modal=modal('เพิ่มห้องเรียน',classForm(),`<button class="btn btn-secondary" data-close-modal>ยกเลิก</button><button class="btn btn-primary" id="save-class">บันทึก</button>`);render()};
 document.querySelectorAll('[data-edit-class]').forEach(b=>b.onclick=()=>{let c=getClassrooms().find(x=>x.id===b.dataset.editClass);state.editing=c.id;state.modal=modal('แก้ไขห้องเรียน',classForm(c),`<button class="btn btn-secondary" data-close-modal>ยกเลิก</button><button class="btn btn-primary" id="save-class">บันทึก</button>`);render()});
 document.querySelectorAll('[data-open-users]').forEach(b=>b.onclick=()=>{state.filters.userRole='user';state.filters.userQ='';state.page='users';render()});
 let sc=document.querySelector('#save-class');if(sc)sc.onclick=()=>{let name=document.querySelector('#cf-name').value.trim();if(!name)return toast('กรอกชื่อห้องเรียน','error');let cls=getClassrooms(),obj={name,level:document.querySelector('#cf-level').value.trim(),room:document.querySelector('#cf-room').value.trim(),studentCount:+document.querySelector('#cf-count').value||0,active:true};if(state.editing)Object.assign(cls.find(x=>x.id===state.editing),obj);else cls.push({id:'C'+Date.now(),...obj});setData('classrooms',cls);audit(state.editing?'UPDATE_CLASSROOM':'CREATE_CLASSROOM',name);state.modal=null;toast('บันทึกห้องเรียนแล้ว');render()};
}
function subjectsPage(){
 let subs=getSubjects(),q=state.filters.subjectQ||'';
 let rows=subs.filter(s=>!q||(`${s.code} ${s.name}`).toLowerCase().includes(q.toLowerCase()));
 return pageHead('รายวิชา','13 รายวิชา/กิจกรรมเริ่มต้น และสามารถเพิ่มได้',`<button class="btn btn-primary" id="new-subject">＋ เพิ่มรายวิชา</button>`)+
 `<div class="toolbar" style="margin-top:18px"><div class="searchbox grow"><span class="mag">⌕</span><input class="field" id="subject-search" placeholder="ค้นหารหัสหรือชื่อรายวิชา" value="${esc(q)}"></div></div><div class="table-wrap"><table class="table"><thead><tr><th>รหัส</th><th>ชื่อรายวิชา/กิจกรรม</th><th>ประเภท</th><th>สถานะ</th><th></th></tr></thead><tbody>${rows.map(s=>`<tr><td><b>${esc(s.code)}</b></td><td>${esc(s.name)}</td><td>${pill(s.type==='subject'?'รายวิชา':'กิจกรรม')}</td><td>${s.active?pill('ใช้งาน','green'):pill('ปิด','red')}</td><td><button class="btn btn-secondary" data-edit-subject="${s.id}">แก้ไข</button></td></tr>`).join('')}</tbody></table></div>`;
}
function subjectForm(s={}){return `<div class="form-grid"><div><label class="label">รหัส</label><input class="field" id="sf-code" value="${esc(s.code||'')}"></div><div><label class="label">ประเภท</label><select class="field" id="sf-type"><option value="subject" ${s.type==='subject'?'selected':''}>รายวิชา</option><option value="activity" ${s.type==='activity'?'selected':''}>กิจกรรม</option></select></div><div class="span-2"><label class="label">ชื่อ</label><input class="field" id="sf-name" value="${esc(s.name||'')}"></div></div>`}
function bindSubjects(){
 let ss=document.querySelector('#subject-search');if(ss)ss.oninput=e=>{state.filters.subjectQ=e.target.value;render()};
 let ns=document.querySelector('#new-subject');if(ns)ns.onclick=()=>{state.editing=null;state.modal=modal('เพิ่มรายวิชา',subjectForm(),`<button class="btn btn-secondary" data-close-modal>ยกเลิก</button><button class="btn btn-primary" id="save-subject">บันทึก</button>`);render()};
 document.querySelectorAll('[data-edit-subject]').forEach(b=>b.onclick=()=>{let s=getSubjects().find(x=>x.id===b.dataset.editSubject);state.editing=s.id;state.modal=modal('แก้ไขรายวิชา',subjectForm(s),`<button class="btn btn-secondary" data-close-modal>ยกเลิก</button><button class="btn btn-primary" id="save-subject">บันทึก</button>`);render()});
 let sv=document.querySelector('#save-subject');if(sv)sv.onclick=()=>{let code=document.querySelector('#sf-code').value.trim(),name=document.querySelector('#sf-name').value.trim();if(!code||!name)return toast('กรอกข้อมูลให้ครบ','error');let subs=getSubjects(),obj={code,name,type:document.querySelector('#sf-type').value,active:true};if(state.editing)Object.assign(subs.find(x=>x.id===state.editing),obj);else subs.push({id:'S'+Date.now(),...obj});setData('subjects',subs);audit(state.editing?'UPDATE_SUBJECT':'CREATE_SUBJECT',code+' '+name);state.modal=null;toast('บันทึกรายวิชาแล้ว');render()};
}
function worksheetsPage(){
 let w=getWorksheets(),q=state.filters.wq||'',status=state.filters.wstatus||'all',type=state.filters.wtype||'all';
 let rows=w.filter(x=>(status==='all'||x.status===status)&&(type==='all'||x.type===type)&&(!q||(`${x.title} ${x.subjectName}`).toLowerCase().includes(q.toLowerCase())));
 return pageHead('ใบงาน','สร้าง จัดการ เผยแพร่ พิมพ์ และติดตามใบงาน',`<button class="btn btn-primary" id="new-worksheet">＋ สร้างใบงาน</button>`)+
 `<div class="toolbar" style="margin-top:18px"><div class="searchbox grow"><span class="mag">⌕</span><input class="field" id="w-search" placeholder="ค้นหาใบงาน" value="${esc(q)}"></div><select class="field" id="w-status"><option value="all">ทุกสถานะ</option><option value="draft" ${status==='draft'?'selected':''}>Draft</option><option value="published" ${status==='published'?'selected':''}>Published</option><option value="closed" ${status==='closed'?'selected':''}>Closed</option></select><select class="field" id="w-type"><option value="all">ทุกประเภท</option><option value="digital" ${type==='digital'?'selected':''}>Digital</option><option value="paper" ${type==='paper'?'selected':''}>Paper</option></select></div>
 <div class="cards">${rows.map(x=>`<article class="card worksheet-card"><div class="action-row">${typePill(x.type)}${statusPill(x.status)}</div><h3>${esc(x.title)}</h3><div class="worksheet-meta"><span>${esc(x.subjectCode)}</span><span>•</span><span>${esc(x.subjectName)}</span></div><div class="small muted">ครบกำหนด ${fmtDate(x.dueAt)}</div><div class="worksheet-actions"><button class="btn btn-secondary" data-edit-w="${x.id}">แก้ไข</button><button class="btn ${x.status==='published'?'btn-danger':'btn-success'}" data-toggle-w="${x.id}">${x.status==='published'?'ยกเลิกเผยแพร่':'เผยแพร่'}</button><button class="btn btn-secondary" data-print-w="${x.id}">🖨 พิมพ์/PDF</button></div></article>`).join('')}</div>`;
}
const STEP_NAMES=['ข้อมูลพื้นฐาน','กลุ่มเป้าหมาย','เวลาและเงื่อนไข','คำถาม','เฉลย/ตรวจ','ตรวจสอบ'];
function worksheetEditor(w=null,step=0){
 let subs=getSubjects(),cls=getClassrooms();w=w||{title:'',subjectId:subs[0]?.id||'',type:'digital',status:'draft',openAt:'2026-09-08T08:00',dueAt:'2026-09-30T23:59',allowLate:false,allowResubmit:true,autosave:true,targetClassroomIds:['C01'],instructions:'',questions:[]};
 state.editing=w.id||null;state.filters.editorStep=step;state.filters.editorObj=clone(w);
 let obj=state.filters.editorObj;
 let content='';
 if(step===0)content=`<div class="form-grid"><div><label class="label">รายวิชา</label><select class="field" id="we-sub">${subs.map(s=>`<option value="${s.id}" ${obj.subjectId===s.id?'selected':''}>${esc(s.code)} · ${esc(s.name)}</option>`).join('')}</select></div><div><label class="label">ประเภทใบงาน</label><select class="field" id="we-type"><option value="digital" ${obj.type==='digital'?'selected':''}>Digital</option><option value="paper" ${obj.type==='paper'?'selected':''}>Paper</option></select></div><div class="span-2"><label class="label">ชื่อใบงาน</label><input class="field" id="we-title" value="${esc(obj.title)}"></div><div class="span-2"><label class="label">คำชี้แจง</label><textarea class="field" id="we-ins" rows="4">${esc(obj.instructions)}</textarea></div></div>`;
 if(step===1)content=`<div><b>เลือกห้องเรียนเป้าหมาย</b><div class="grid-3" style="margin-top:12px">${cls.map(c=>`<label class="card" style="box-shadow:none"><input type="checkbox" data-target-class value="${c.id}" ${obj.targetClassroomIds.includes(c.id)?'checked':''}> <b>${esc(c.name)}</b><div class="small muted">${c.studentCount} คน</div></label>`).join('')}</div></div>`;
 if(step===2)content=`<div class="form-grid"><div><label class="label">วันเวลาเปิด</label><input class="field" id="we-open" type="datetime-local" value="${obj.openAt}"></div><div><label class="label">วันเวลาครบกำหนด</label><input class="field" id="we-due" type="datetime-local" value="${obj.dueAt}"></div><label class="card" style="box-shadow:none"><input type="checkbox" id="we-late" ${obj.allowLate?'checked':''}> อนุญาตส่งช้า</label><label class="card" style="box-shadow:none"><input type="checkbox" id="we-resubmit" ${obj.allowResubmit?'checked':''}> อนุญาตส่งแก้ไข</label><label class="card" style="box-shadow:none"><input type="checkbox" id="we-autosave" ${obj.autosave?'checked':''}> บันทึกร่างอัตโนมัติ</label></div>`;
 if(step===3)content=`<div><div class="page-head"><div><b>คำถาม ${obj.questions.length} ข้อ</b><p class="small muted">รองรับ Single Choice / Multiple Choice / Short Answer / Paragraph / Code / File / Drawing</p></div><button class="btn btn-primary" id="add-question">＋ เพิ่มคำถาม</button></div>${obj.questions.length?obj.questions.map((q,i)=>`<div class="question-builder"><div class="question-head"><b>ข้อ ${i+1} · ${esc(q.type)}</b><button class="btn btn-danger" data-del-q="${q.id}">ลบ</button></div><div style="margin-top:10px">${esc(q.text)}</div></div>`).join(''):'<div class="empty" style="margin-top:12px">ยังไม่มีคำถาม</div>'}</div>`;
 if(step===4)content=`<div><h3>เฉลยและการตรวจอัตโนมัติ</h3><div class="warn-box">🔒 ใน Production เฉลยจะเก็บใน <b>worksheetAnswerKeys</b> และ User ไม่มีสิทธิ์อ่าน ส่วนคะแนนเก็บใน <b>submissionGrades</b> เท่านั้น</div><div class="card" style="box-shadow:none;margin-top:14px"><b>Auto grade</b><p class="small muted">Single/Multiple Choice สามารถตรวจอัตโนมัติได้ ส่วน Paragraph/Code/File ใช้ครูตรวจ</p></div></div>`;
 if(step===5)content=`<div><h3>ตรวจสอบก่อนบันทึก</h3><div class="grid-3"><div class="card" style="box-shadow:none"><span class="muted small">ชื่อใบงาน</span><div><b>${esc(obj.title||'ยังไม่ระบุ')}</b></div></div><div class="card" style="box-shadow:none"><span class="muted small">คำถาม</span><div><b>${obj.questions.length} ข้อ</b></div></div><div class="card" style="box-shadow:none"><span class="muted small">เป้าหมาย</span><div><b>${obj.targetClassroomIds.length} ห้อง</b></div></div></div><div class="success-box" style="margin-top:14px">พร้อมบันทึกเป็น Draft หรือเผยแพร่ทันที</div></div>`;
 return pageHead(state.editing?'แก้ไขใบงาน':'สร้างใบงาน','Wizard 6 ขั้นตอน · บันทึก Draft ได้ทุกขั้น',`<button class="btn btn-secondary" data-go="worksheets">← กลับ</button>`)+
 `<div class="stepper">${STEP_NAMES.map((n,i)=>`<button class="step ${i===step?'active':i<step?'done':''}" data-step="${i}">${i+1}. ${n}</button>`).join('')}</div><section class="card" style="margin-top:14px">${content}<div style="display:flex;justify-content:space-between;gap:10px;border-top:1px solid #eef2f7;margin-top:18px;padding-top:16px"><button class="btn btn-secondary" id="save-draft">💾 บันทึก Draft</button><div class="action-row">${step>0?'<button class="btn btn-secondary" id="prev-step">ก่อนหน้า</button>':''}${step<5?'<button class="btn btn-primary" id="next-step">ถัดไป →</button>':'<button class="btn btn-primary" id="publish-final">บันทึกและเผยแพร่</button>'}</div></div></section>`;
}
function syncEditor(){
 let o=state.filters.editorObj;if(!o)return;
 if(document.querySelector('#we-title')){o.title=document.querySelector('#we-title').value;o.instructions=document.querySelector('#we-ins').value;o.subjectId=document.querySelector('#we-sub').value;o.type=document.querySelector('#we-type').value}
 if(document.querySelector('[data-target-class]'))o.targetClassroomIds=[...document.querySelectorAll('[data-target-class]:checked')].map(x=>x.value);
 if(document.querySelector('#we-open')){o.openAt=document.querySelector('#we-open').value;o.dueAt=document.querySelector('#we-due').value;o.allowLate=document.querySelector('#we-late').checked;o.allowResubmit=document.querySelector('#we-resubmit').checked;o.autosave=document.querySelector('#we-autosave').checked}
}
function saveEditor(publish=false){
 syncEditor();let o=state.filters.editorObj,subs=getSubjects(),s=subs.find(x=>x.id===o.subjectId);if(!o.title.trim())return toast('กรุณาระบุชื่อใบงาน','error');
 Object.assign(o,{subjectCode:s?.code||'',subjectName:s?.name||'',status:publish?'published':'draft'});
 let w=getWorksheets();if(state.editing)Object.assign(w.find(x=>x.id===state.editing),o);else{o.id='W'+Date.now();o.createdAt=new Date().toISOString();w.unshift(o);state.editing=o.id}
 setData('worksheets',w);audit(publish?'PUBLISH_WORKSHEET':(state.editing?'SAVE_WORKSHEET':'CREATE_WORKSHEET'),o.title);toast(publish?'เผยแพร่ใบงานแล้ว':'บันทึก Draft แล้ว');if(publish){state.page='worksheets';state.filters.editorObj=null;render()}
}
function bindWorksheets(){
 let qs=document.querySelector('#w-search');if(qs)qs.oninput=e=>{state.filters.wq=e.target.value;render()};
 let st=document.querySelector('#w-status');if(st)st.onchange=e=>{state.filters.wstatus=e.target.value;render()};
 let ty=document.querySelector('#w-type');if(ty)ty.onchange=e=>{state.filters.wtype=e.target.value;render()};
 let nw=document.querySelector('#new-worksheet');if(nw)nw.onclick=()=>{state.page='worksheets:new';state.filters.editorObj=null;state.editing=null;render()};
 document.querySelectorAll('[data-edit-w]').forEach(b=>b.onclick=()=>{state.page='worksheets:edit';state.filters.editorObj=clone(getWorksheets().find(x=>x.id===b.dataset.editW));state.editing=b.dataset.editW;state.filters.editorStep=0;render()});
 document.querySelectorAll('[data-toggle-w]').forEach(b=>b.onclick=()=>{let w=getWorksheets(),x=w.find(z=>z.id===b.dataset.toggleW);x.status=x.status==='published'?'draft':'published';setData('worksheets',w);audit(x.status==='published'?'PUBLISH_WORKSHEET':'UNPUBLISH_WORKSHEET',x.title);toast('อัปเดตสถานะใบงานแล้ว');render()});
 document.querySelectorAll('[data-print-w]').forEach(b=>b.onclick=()=>{state.page='worksheets:print:'+b.dataset.printW;render()});
}
function bindEditor(){
 document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{syncEditor();state.filters.editorStep=+b.dataset.step;render()});
 let nx=document.querySelector('#next-step');if(nx)nx.onclick=()=>{syncEditor();state.filters.editorStep=Math.min(5,(state.filters.editorStep||0)+1);render()};
 let pr=document.querySelector('#prev-step');if(pr)pr.onclick=()=>{syncEditor();state.filters.editorStep=Math.max(0,(state.filters.editorStep||0)-1);render()};
 let sd=document.querySelector('#save-draft');if(sd)sd.onclick=()=>saveEditor(false);
 let pf=document.querySelector('#publish-final');if(pf)pf.onclick=()=>saveEditor(true);
 let aq=document.querySelector('#add-question');if(aq)aq.onclick=()=>{syncEditor();state.modal=modal('เพิ่มคำถาม',`<div class="form-grid"><div><label class="label">ประเภท</label><select class="field" id="q-type"><option value="singleChoice">Single Choice</option><option value="multipleChoice">Multiple Choice</option><option value="shortAnswer">Short Answer</option><option value="paragraph">Paragraph</option><option value="codeEditor">Code Editor</option><option value="fileUpload">File Upload</option><option value="drawingArea">Drawing Area</option></select></div><div class="span-2"><label class="label">คำถาม</label><textarea class="field" id="q-text" rows="3"></textarea></div><div class="span-2"><label class="label">ตัวเลือก (คั่นด้วย | สำหรับ Choice)</label><input class="field" id="q-choices" placeholder="A | B | C | D"></div></div>`,`<button class="btn btn-secondary" data-close-modal>ยกเลิก</button><button class="btn btn-primary" id="save-question">เพิ่มคำถาม</button>`);render()};
 document.querySelectorAll('[data-del-q]').forEach(b=>b.onclick=()=>{state.filters.editorObj.questions=state.filters.editorObj.questions.filter(q=>q.id!==b.dataset.delQ);render()});
 let sq=document.querySelector('#save-question');if(sq)sq.onclick=()=>{let text=document.querySelector('#q-text').value.trim(),type=document.querySelector('#q-type').value;if(!text)return toast('กรอกคำถาม','error');let choices=document.querySelector('#q-choices').value.split('|').map(x=>x.trim()).filter(Boolean);state.filters.editorObj.questions.push({id:uid(),type,text,choices,required:true});state.modal=null;toast('เพิ่มคำถามแล้ว');render()};
}
function printWorksheetPage(id){
 let w=getWorksheets().find(x=>x.id===id);if(!w)return '<div class="empty">ไม่พบใบงาน</div>';
 return `<div class="no-print" style="margin-bottom:12px"><button class="btn btn-secondary" data-go="worksheets">← กลับ</button> <button class="btn btn-primary" id="print-now">🖨 พิมพ์ / Save PDF</button></div><section class="print-sheet"><div style="text-align:center"><h1>${esc(w.title)}</h1><p>${esc(w.subjectCode)} · ${esc(w.subjectName)}</p></div><hr><p><b>ชื่อ-สกุล ________________________________________ ชั้น __________ เลขที่ ________</b></p><p>${esc(w.instructions)}</p>${w.questions.map((q,i)=>`<div style="margin-top:24px"><b>${i+1}. ${esc(q.text)}</b>${q.choices?.length?q.choices.map((c,j)=>`<div style="margin:8px 0">☐ ${esc(c)}</div>`).join(''):'<div class="print-line"></div>'}</div>`).join('')}<div style="margin-top:30px;text-align:right" class="small">DOC-FULL-NR Smart Worksheet · ${new Date().toLocaleDateString('th-TH')}</div></section>`;
}
function gradingPage(){
 let s=getSubmissions(),g=getGrades(),w=getWorksheets(),users=getUsers();
 return pageHead('ตรวจงาน','ตรวจคำตอบ ให้คะแนน และบันทึกความเห็นเฉพาะ Admin')+
 `<div class="table-wrap"><table class="table"><thead><tr><th>ผู้เรียน</th><th>ใบงาน</th><th>ส่งเมื่อ</th><th>สถานะ</th><th>คะแนน</th><th></th></tr></thead><tbody>${s.length?s.map(x=>{let ww=w.find(a=>a.id===x.worksheetId),u=users.find(a=>a.id===x.userId),gr=g.find(a=>a.submissionId===x.id);return `<tr><td><b>${esc(u?.name||x.userName||'-')}</b></td><td>${esc(ww?.title||x.worksheetId)}</td><td>${fmtDate(x.submittedAt)}</td><td>${pill(x.status||'submitted','green')}</td><td><b>${gr?gr.score+'/100':'-'}</b></td><td><button class="btn btn-primary" data-grade="${x.id}">${gr?'แก้คะแนน':'ตรวจงาน'}</button></td></tr>`}).join(''):'<tr><td colspan="6"><div class="empty">ยังไม่มีงานส่ง — ให้ทดลอง User ส่งงานก่อน</div></td></tr>'}</tbody></table></div>`;
}
function bindGrading(){
 document.querySelectorAll('[data-grade]').forEach(b=>b.onclick=()=>{let s=getSubmissions().find(x=>x.id===b.dataset.grade),g=getGrades(),old=g.find(x=>x.submissionId===s.id);state.modal=modal('ตรวจและให้คะแนน',`<div><div class="warn-box">คะแนน/ความเห็นหน้านี้เป็นข้อมูล Admin เท่านั้น ฝั่ง User จะไม่แสดง</div><div style="margin-top:14px"><label class="label">คะแนน 0–100</label><input class="field" type="number" min="0" max="100" id="grade-score" value="${old?.score??''}"></div><div style="margin-top:14px"><label class="label">ความเห็นผู้ตรวจ</label><textarea class="field" id="grade-comment" rows="4">${esc(old?.comment||'')}</textarea></div></div>`,`<button class="btn btn-secondary" data-close-modal>ยกเลิก</button><button class="btn btn-primary" id="save-grade">บันทึกคะแนน</button>`);state.editing=s.id;render()});
 let sg=document.querySelector('#save-grade');if(sg)sg.onclick=()=>{let score=Math.max(0,Math.min(100,+document.querySelector('#grade-score').value||0)),comment=document.querySelector('#grade-comment').value.trim(),g=getGrades().filter(x=>x.submissionId!==state.editing);g.push({id:uid(),submissionId:state.editing,score,comment,gradedAt:new Date().toISOString(),graderId:currentUser().id});setData('grades',g);audit('GRADE_SUBMISSION',state.editing+' score='+score);state.modal=null;toast('บันทึกคะแนนแล้ว');render()};
}
function reportsPage(){
 let s=getSubmissions(),g=getGrades(),w=getWorksheets();
 let graded=s.filter(x=>g.some(y=>y.submissionId===x.id)).length,late=s.filter(x=>x.isLate).length;
 return pageHead('รายงาน','กรอง Preview และ Export CSV',`<button class="btn btn-primary" id="export-csv">⬇ Export CSV</button>`)+
 `<div class="stats">${stat('▧','ใบงาน',w.length)}${stat('↥','ส่งงาน',s.length)}${stat('✓','ตรวจแล้ว',graded)}${stat('!','ส่งช้า',late)}</div><section class="card" style="margin-top:16px"><div class="form-grid"><div><label class="label">ประเภทรายงาน</label><select class="field"><option>สถานะการส่งงาน</option><option>ผู้ที่ยังไม่ส่ง</option><option>ผู้ที่ส่งช้า</option><option>คะแนน (Admin)</option></select></div><div><label class="label">ช่วงวันที่</label><input class="field" type="date"></div></div></section>
 <div class="table-wrap"><table class="table"><thead><tr><th>ใบงาน</th><th>ผู้เรียน</th><th>ส่งเมื่อ</th><th>คะแนน</th></tr></thead><tbody>${s.map(x=>{let ww=w.find(a=>a.id===x.worksheetId),gr=g.find(a=>a.submissionId===x.id);return `<tr><td>${esc(ww?.title||x.worksheetId)}</td><td>${esc(x.userName||x.userId)}</td><td>${fmtDate(x.submittedAt)}</td><td>${gr?.score??'-'}</td></tr>`}).join('')}</tbody></table></div>`;
}
function bindReports(){
 let b=document.querySelector('#export-csv');if(!b)return;b.onclick=()=>{let s=getSubmissions(),g=getGrades(),w=getWorksheets(),rows=[['Worksheet','Student','SubmittedAt','Late','Score'],...s.map(x=>{let ww=w.find(a=>a.id===x.worksheetId),gr=g.find(a=>a.submissionId===x.id);return [ww?.title||x.worksheetId,x.userName||x.userId,x.submittedAt,x.isLate?'Y':'N',gr?.score??'']})],csv='\uFEFF'+rows.map(r=>r.map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')).join('\r\n'),blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='doc-full-nr-report.csv';a.click();URL.revokeObjectURL(a.href);audit('EXPORT_REPORT','CSV');toast('ดาวน์โหลด CSV แล้ว')};
}
