function settingsPage(){
 let s=getSettings();
 return pageHead('ตั้งค่าระบบ','ข้อมูลสถานศึกษา ภาคเรียน และนโยบายพื้นฐาน')+`<section class="card" style="margin-top:16px"><div class="form-grid"><div><label class="label">สถานศึกษา</label><input class="field" id="set-school" value="${esc(s.schoolName)}"></div><div><label class="label">แผนก</label><input class="field" id="set-dept" value="${esc(s.department)}"></div><div><label class="label">ภาคเรียน</label><input class="field" id="set-sem" value="${esc(s.semester)}"></div><div><label class="label">นโยบายส่งช้า</label><select class="field" id="set-late"><option value="allow-by-worksheet" ${s.latePolicy==='allow-by-worksheet'?'selected':''}>ตามเงื่อนไขใบงาน</option><option value="deny" ${s.latePolicy==='deny'?'selected':''}>ไม่อนุญาต</option></select></div></div><button class="btn btn-primary" id="save-settings" style="margin-top:16px">บันทึกการตั้งค่า</button></section><div class="danger-box" style="margin-top:16px"><b>Production Security</b><br>Firebase Rules ต้อง Default-deny, งาน Sensitive ใช้ Cloud Functions, User ต้องอ่านไม่ได้ทั้ง worksheetAnswerKeys และ submissionGrades</div>`;
}
function bindSettings(){let b=document.querySelector('#save-settings');if(b)b.onclick=()=>{setData('settings',{schoolName:document.querySelector('#set-school').value.trim(),department:document.querySelector('#set-dept').value.trim(),semester:document.querySelector('#set-sem').value.trim(),latePolicy:document.querySelector('#set-late').value});audit('UPDATE_SETTINGS','system');toast('บันทึกการตั้งค่าแล้ว');render()}}
function profilePageAdmin(){let u=currentUser();return pageHead('โปรไฟล์','ข้อมูลผู้ดูแลระบบ')+`<div class="profile-grid" style="margin-top:16px"><section class="card profile-card"><div class="avatar">${esc(u.name.slice(0,1))}</div><h3>${esc(u.name)}</h3>${pill('Administrator','red')}</section><section class="card"><div class="form-grid"><div><label class="label">ชื่อ</label><input class="field" value="${esc(u.name)}" disabled></div><div><label class="label">อีเมล</label><input class="field" value="${esc(u.email)}" disabled></div></div></section></div>`}
function userDashboard(){
 let u=currentUser(),w=getUserWorksheets(),s=getSubmissions().filter(x=>x.userId===u.id);
 let due=w.filter(x=>!s.some(y=>y.worksheetId===x.id)).slice(0,5);
 return pageHead('สวัสดี '+esc(u.name),'ติดตามใบงานและสถานะการส่งงาน')+`<div class="stats">${stat('▧','ใบงานที่เปิด',w.length)}${stat('✓','ส่งแล้ว',s.length)}${stat('⌛','รอดำเนินการ',Math.max(0,w.length-s.length))}${stat('♙','ห้องเรียน',esc(getClassrooms().find(c=>c.id===u.classroomId)?.name||'-'))}</div><section class="card" style="margin-top:16px"><b>งานที่ควรทำต่อ</b><div style="margin-top:10px">${due.length?due.map(x=>`<div style="display:flex;justify-content:space-between;gap:10px;padding:12px 0;border-bottom:1px solid #eef2f7"><div><b>${esc(x.title)}</b><div class="small muted">${esc(x.subjectName)}</div></div><button class="btn btn-primary" data-do-user="${x.id}">${x.type==='paper'?'ดูใบงาน':'ทำใบงาน'}</button></div>`).join(''):'<div class="empty">ส่งงานครบแล้ว 🎉</div>'}</div></section><div class="success-box" style="margin-top:16px">ฝั่ง User นี้ไม่แสดงคะแนน เฉลย Rubric หรือความเห็น Admin</div>`;
}
function getUserWorksheets(){
 let u=currentUser();return getWorksheets().filter(w=>w.status==='published'&&(w.targetClassroomIds||[]).includes(u.classroomId));
}
function userWorksheets(){
 let w=getUserWorksheets(),s=getSubmissions(),q=state.filters.uwq||'',type=state.filters.uwtype||'all';
 let rows=w.filter(x=>(type==='all'||x.type===type)&&(!q||(`${x.title} ${x.subjectName}`).toLowerCase().includes(q.toLowerCase())));
 return pageHead('ใบงานของฉัน','ใบงานที่ได้รับมอบหมายและเปิดรับอยู่')+`<div class="toolbar" style="margin-top:18px"><div class="searchbox grow"><span class="mag">⌕</span><input class="field" id="uw-search" placeholder="ค้นหาใบงาน" value="${esc(q)}"></div><select class="field" id="uw-type"><option value="all">ทุกประเภท</option><option value="digital" ${type==='digital'?'selected':''}>Digital</option><option value="paper" ${type==='paper'?'selected':''}>Paper</option></select></div><div class="cards">${rows.map(x=>{let sub=s.find(y=>y.worksheetId===x.id&&y.userId===currentUser().id);return `<article class="card worksheet-card"><div class="action-row">${typePill(x.type)}${sub?pill('ส่งแล้ว','green'):pill('ยังไม่ส่ง','amber')}</div><h3>${esc(x.title)}</h3><div class="worksheet-meta">${esc(x.subjectCode)} · ${esc(x.subjectName)}</div><div class="small muted">ครบกำหนด ${fmtDate(x.dueAt)}</div><div class="worksheet-actions"><button class="btn btn-primary" data-do-user="${x.id}">${x.type==='paper'?'เปิด/พิมพ์':'ทำใบงาน'}</button></div></article>`}).join('')}</div>`;
}
function worksheetDoPage(id){
 let w=getWorksheets().find(x=>x.id===id);if(!w)return '<div class="empty">ไม่พบใบงาน</div>';
 let sub=getSubmissions().find(x=>x.worksheetId===w.id&&x.userId===currentUser().id);
 if(w.type==='paper')return pageHead(w.title,w.subjectCode+' · '+w.subjectName,`<button class="btn btn-secondary" data-go="worksheets">← กลับ</button>`)+`<section class="card" style="margin-top:16px"><div class="warn-box">ใบงานชนิด Paper — สามารถพิมพ์ใบงานและยืนยันการส่งกระดาษ</div><div class="action-row" style="margin-top:14px"><button class="btn btn-secondary" id="user-print-paper">🖨 พิมพ์ใบงาน</button><button class="btn btn-primary" id="confirm-paper" data-id="${w.id}">${sub?'ยืนยันส่งใหม่':'ยืนยันส่ง Paper'}</button></div></section>`;
 let draft=load('draft.'+w.id,{});
 return pageHead(w.title,w.subjectCode+' · '+w.subjectName,`<button class="btn btn-secondary" data-go="worksheets">← กลับ</button>`)+`<div class="warn-box" style="margin-top:16px">ครบกำหนด: ${fmtDate(w.dueAt)} · <span class="countdown" data-due="${w.dueAt}"></span></div><form class="card" id="answer-form" style="margin-top:16px">${w.questions.map((q,i)=>`<div class="question"><b>${i+1}. ${esc(q.text)} ${q.required?'<span style="color:#dc2626">*</span>':''}</b>${renderAnswerInput(q,draft[q.id])}</div>`).join('')}<div class="action-row" style="margin-top:18px"><button type="button" class="btn btn-secondary" id="save-answer-draft">💾 บันทึกร่าง</button><button type="submit" class="btn btn-primary">ส่งงาน</button></div></form>`;
}
function renderAnswerInput(q,v){
 if(q.type==='singleChoice')return (q.choices||[]).map(c=>`<label class="choice"><input type="radio" name="${q.id}" value="${esc(c)}" ${v===c?'checked':''}> ${esc(c)}</label>`).join('');
 if(q.type==='multipleChoice')return (q.choices||[]).map(c=>`<label class="choice"><input type="checkbox" name="${q.id}" value="${esc(c)}" ${Array.isArray(v)&&v.includes(c)?'checked':''}> ${esc(c)}</label>`).join('');
 if(q.type==='fileUpload')return `<input class="field" type="file" name="${q.id}">`;
 if(q.type==='codeEditor')return `<textarea class="field" name="${q.id}" rows="8" style="font-family:monospace" placeholder="เขียนโค้ดที่นี่">${esc(v||'')}</textarea>`;
 if(q.type==='drawingArea')return `<div class="empty">Drawing Area (UX พร้อมเชื่อม Canvas component)</div>`;
 return `<textarea class="field" name="${q.id}" rows="${q.type==='paragraph'?6:3}" placeholder="พิมพ์คำตอบ">${esc(v||'')}</textarea>`;
}
function collectAnswers(form){
 let ans={};getWorksheets().find(x=>state.page.endsWith(x.id))?.questions.forEach(q=>{if(q.type==='multipleChoice')ans[q.id]=[...form.querySelectorAll(`[name="${q.id}"]:checked`)].map(x=>x.value);else if(q.type==='fileUpload')ans[q.id]=form.querySelector(`[name="${q.id}"]`)?.files?.[0]?.name||'';else ans[q.id]=form.querySelector(`[name="${q.id}"]:checked`)?.value??form.querySelector(`[name="${q.id}"]`)?.value??''});return ans
}
function submitUserWork(id,answers,kind='digital'){
 let w=getWorksheets().find(x=>x.id===id),due=new Date(w.dueAt).getTime(),isLate=Date.now()>due,s=getSubmissions(),idx=s.findIndex(x=>x.worksheetId===id&&x.userId===currentUser().id);
 if(isLate&&!w.allowLate)return toast('ใบงานนี้ไม่อนุญาตส่งหลังครบกำหนด','error');
 if(idx>=0&&!w.allowResubmit)return toast('ใบงานนี้ไม่อนุญาตส่งซ้ำ','error');
 let obj={id:idx>=0?s[idx].id:uid(),worksheetId:id,userId:currentUser().id,userName:currentUser().name,type:kind,answers,submittedAt:new Date().toISOString(),isLate,status:'submitted'};if(idx>=0)s[idx]=obj;else s.push(obj);setData('submissions',s);localStorage.removeItem(STORE+'draft.'+id);audit(kind==='paper'?'CONFIRM_PAPER_SUBMISSION':'SUBMIT_DIGITAL_WORKSHEET',w.title,currentUser().name);toast('ส่งงานสำเร็จ');state.page='worksheets';render();
}
async function startCamera(){
 if(!navigator.mediaDevices?.getUserMedia)return toast('เบราว์เซอร์ไม่รองรับกล้อง','error');
 try{let video=document.querySelector('#scan-video');state.scanStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});video.srcObject=state.scanStream;await video.play();document.querySelector('#camera-placeholder').classList.add('hidden');if('BarcodeDetector'in window)detectLoop(video)}catch(e){toast('ไม่สามารถเปิดกล้องได้ กรุณาอนุญาตสิทธิ์กล้อง','error')}
}
async function detectLoop(video){
 try{
   let detector=new BarcodeDetector({formats:['qr_code','code_128','ean_13']});
   while(state.scanStream){
     let codes=await detector.detect(video);
     if(codes.length){
       document.querySelector('#scan-code').value=codes[0].rawValue;
       toast('อ่านโค้ดสำเร็จ');
       stopCamera();
       break;
     }
     await new Promise(r=>setTimeout(r,450));
   }
 }catch{}
}
function stopCamera(){if(state.scanStream)state.scanStream.getTracks().forEach(t=>t.stop());state.scanStream=null}
function scanPage(){
 return pageHead('สแกน QR / Barcode','เปิดใบงานจากรหัสหรือกล้อง')+`<section class="card scan-box"><div class="camera"><div id="camera-placeholder"><div style="font-size:64px">⌗</div><div>กดเปิดกล้องเพื่อสแกน</div></div><video id="scan-video" playsinline></video><div class="scan-frame"></div></div><div class="action-row" style="justify-content:center;margin-top:14px"><button class="btn btn-primary" id="start-camera">📷 เปิดกล้อง</button><button class="btn btn-secondary" id="stop-camera">หยุดกล้อง</button></div><div style="margin-top:16px;text-align:left"><label class="label">รหัสใบงาน / QR Payload</label><input class="field" id="scan-code" placeholder="เช่น W01"><button class="btn btn-primary" id="open-scan" style="margin-top:10px;width:100%">เปิดใบงาน</button></div><p class="small muted">กล้องใช้ BarcodeDetector เมื่อ Browser รองรับ; หากไม่รองรับสามารถกรอกรหัสเองได้</p></section>`;
}
function userProfile(){
 let u=currentUser(),c=getClassrooms().find(x=>x.id===u.classroomId),sub=getSubmissions().filter(x=>x.userId===u.id);
 return pageHead('โปรไฟล์','ข้อมูลบัญชีและห้องเรียน')+`<div class="profile-grid" style="margin-top:16px"><section class="card profile-card"><div class="avatar">${esc(u.name.slice(0,1))}</div><h3>${esc(u.name)}</h3>${pill('User')}<p class="small muted">${esc(u.email)}</p></section><section class="card"><div class="form-grid"><div><label class="label">ห้องเรียน</label><input class="field" value="${esc(c?.name||'-')}" disabled></div><div><label class="label">ส่งงานแล้ว</label><input class="field" value="${sub.length} รายการ" disabled></div></div><div class="success-box" style="margin-top:16px">เพื่อความเป็นส่วนตัว หน้านี้ไม่ดึงข้อมูลคะแนนหรือข้อมูล Admin</div></section></div>`;
}
function bindUserPages(){
 document.querySelectorAll('[data-do-user]').forEach(b=>b.onclick=()=>{state.page='worksheets:do:'+b.dataset.doUser;render()});
 let qs=document.querySelector('#uw-search');if(qs)qs.oninput=e=>{state.filters.uwq=e.target.value;render()};
 let ty=document.querySelector('#uw-type');if(ty)ty.onchange=e=>{state.filters.uwtype=e.target.value;render()};
 let f=document.querySelector('#answer-form');if(f){document.querySelector('#save-answer-draft').onclick=()=>{let id=state.page.split(':').pop(),ans=collectAnswers(f);save('draft.'+id,ans);audit('SAVE_DRAFT',id,currentUser().name);toast('บันทึกร่างแล้ว')};f.onsubmit=e=>{e.preventDefault();submitUserWork(state.page.split(':').pop(),collectAnswers(f),'digital')}}
 let cp=document.querySelector('#confirm-paper');if(cp)cp.onclick=()=>submitUserWork(cp.dataset.id,{paperConfirmed:true},'paper');
 let pp=document.querySelector('#user-print-paper');if(pp)pp.onclick=()=>{let id=state.page.split(':').pop();state.page='worksheets:print-user:'+id;render()};
 let sc=document.querySelector('#start-camera');if(sc)sc.onclick=startCamera;let st=document.querySelector('#stop-camera');if(st)st.onclick=stopCamera;
 let os=document.querySelector('#open-scan');if(os)os.onclick=()=>{let raw=document.querySelector('#scan-code').value.trim(),id=(raw.match(/W\d+/i)||[raw])[0].toUpperCase(),w=getUserWorksheets().find(x=>x.id===id);if(!w)return toast('ไม่พบใบงานที่เปิดรับสำหรับรหัสนี้','error');state.page='worksheets:do:'+id;render()};
}
function render(){
 if(!state.role)return renderLogin();
 let content='';
 if(state.role==='admin'){
   if(state.page==='dashboard')content=adminDashboard();
   else if(state.page==='users')content=usersPage();
   else if(state.page==='classrooms')content=classroomsPage();
   else if(state.page==='subjects')content=subjectsPage();
   else if(state.page==='worksheets')content=worksheetsPage();
   else if(state.page==='worksheets:new'||state.page==='worksheets:edit')content=worksheetEditor(state.filters.editorObj||null,state.filters.editorStep||0);
   else if(state.page.startsWith('worksheets:print:'))content=printWorksheetPage(state.page.split(':').pop());
   else if(state.page==='grading')content=gradingPage();
   else if(state.page==='reports')content=reportsPage();
   else if(state.page==='audit')content=auditPage();
   else if(state.page==='settings')content=settingsPage();
   else content=profilePageAdmin();
 }else{
   if(state.page==='dashboard')content=userDashboard();
   else if(state.page==='worksheets')content=userWorksheets();
   else if(state.page.startsWith('worksheets:do:'))content=worksheetDoPage(state.page.split(':').pop());
   else if(state.page.startsWith('worksheets:print-user:'))content=printWorksheetPage(state.page.split(':').pop());
   else if(state.page==='scan')content=scanPage();
   else content=userProfile();
 }
 app.innerHTML=shell(content);bindShell();
 document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{state.page=b.dataset.go;render()});
 let rd=document.querySelector('#reset-demo');if(rd)rd.onclick=()=>{if(confirm('รีเซ็ตข้อมูลทดสอบทั้งหมดหรือไม่?'))resetDemo()};
 if(state.role==='admin'){bindUsers();bindClassrooms();bindSubjects();bindWorksheets();bindEditor();bindGrading();bindReports();bindSettings();let pn=document.querySelector('#print-now');if(pn)pn.onclick=()=>window.print()}
 else bindUserPages();
 countdowns();
}
render();
